"""Test whether d(n)=A_{n+1}-kappa(n+1) is generated by a tau-uniform substitution on its own values:
does d(n) determine the block d(tau*n+c+j), j<tau, for some shift c? Report conflicts."""
import numpy as np,sys
D=int(sys.argv[1]); q=D+1; f=np.memmap(f'd_1_{D}.bin' if len(sys.argv)<3 else sys.argv[2],dtype=np.int8,mode='r')
N=min(len(f)//q-2,3_000_000); x=np.asarray(f[:N*q+2*q]).astype(np.int64)
for c in range(-1,q+1):
    m={}; bad=0
    for n in range(2,N):
        blk=tuple(x[q*n+c:q*n+c+q]); k=int(x[n])
        if m.setdefault(k,blk)!=blk: bad+=1
    print('shift',c,'letters',len(m),'conflicts',bad)
